// ======================================================================
// HELPERS de fecha (timezone Argentina)
// ======================================================================
function fmtArgentina(d) {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'America/Argentina/Buenos_Aires',
    year: 'numeric', month: '2-digit', day: '2-digit'
  }).formatToParts(d);
  const y = parts.find(p => p.type === 'year').value;
  const m = parts.find(p => p.type === 'month').value;
  const dd = parts.find(p => p.type === 'day').value;
  return `${y}-${m}-${dd}`;
}

function addDays(yyyy_mm_dd, n) {
  const [y, m, d] = yyyy_mm_dd.split('-').map(Number);
  const date = new Date(Date.UTC(y, m - 1, d));
  date.setUTCDate(date.getUTCDate() + n);
  const yy = date.getUTCFullYear();
  const mm = String(date.getUTCMonth() + 1).padStart(2, '0');
  const dd = String(date.getUTCDate()).padStart(2, '0');
  return `${yy}-${mm}-${dd}`;
}

function hoyArgentina() {
  return fmtArgentina(new Date());
}

// ======================================================================
// INPUT
// ======================================================================
const input = ($input.all()[0] && $input.all()[0].json) || {};
const chatId = input.chat_id;
const comando = input.comando || 'crear';
const textRaw = String(input.text || '');
const payload = input.payload || {};

// ======================================================================
// STATIC DATA: memoria persistente del workflow
// ======================================================================
const staticData = $getWorkflowStaticData('global');
const ctxKey = chatId ? 'ctx_' + chatId : null;
const capturaKey = chatId ? 'captura_' + chatId : null;

// ======================================================================
// CAPTURA EN CURSO (design § D3/D4, c-27): si el orquestador reenvio esta
// respuesta como respuesta_captura, esta ejecucion responde una pregunta
// de identidad pendiente, no un paso de fecha/hora -- se deriva a
// Code - Procesar Captura y se corta ACA el resto de la logica de
// creacion (no tiene sentido calcular fecha/slot para un DNI).
if (payload.respuesta_captura !== undefined) {
  return [{
    json: {
      chat_id: chatId,
      comando: comando,
      accion: 'captura',
      respuesta_captura: String(payload.respuesta_captura),
      fecha: '',
      slot: '',
      rango: '',
      fecha_inicio: '',
      mensaje_error: ''
    }
  }];
}

let fecha = payload.fecha || '';
let slot = payload.slot || '';
let slotNumero = payload.slot_numero || 0;
let rango = payload.rango || '';
let fechaRaw = payload.fecha_raw || '';
let accion = '';
let mensajeError = '';

// Start limpio: un cmd:crear sin datos ancla el contexto viejo. Tambien
// limpia captura_ (c-27): una reserva nueva no debe arrastrar una captura
// abandonada de una reserva anterior.
const freshStart = textRaw === 'cmd:crear' && Object.keys(payload).length === 0;
if (freshStart && ctxKey) {
  delete staticData[ctxKey];
  delete staticData['contador_' + chatId];
  delete staticData['fecha_' + chatId];
  if (capturaKey) delete staticData[capturaKey];
}

const ctx = ctxKey ? (staticData[ctxKey] || {}) : {};

// Si no tenemos fecha en el input, leerla de staticData
if (!fecha && ctx.fecha) fecha = ctx.fecha;
if (!rango && ctx.rango) rango = ctx.rango;

// Si nos llegó slot_numero, resolverlo a slot real desde los slots guardados
if (slotNumero && !slot) {
  const slotsGuardados = ctx.slots || [];
  const idx = slotNumero - 1;
  if (idx >= 0 && idx < slotsGuardados.length) {
    slot = slotsGuardados[idx].hora_inicio;
  }
}

// Defensa: parsear callbacks de slot (formato HH:MM:f:YYYY-MM-DD)
if (textRaw.startsWith('cmd:crear:slot:')) {
  const parsed = textRaw.substring('cmd:crear:slot:'.length);
  if (parsed !== 'none') {
    const fIdx = parsed.indexOf(':f:');
    if (fIdx >= 0) {
      slot = parsed.substring(0, fIdx);
      if (!fecha) fecha = parsed.substring(fIdx + 3);
    } else {
      slot = parsed;
    }
  }
}

// ======================================================================
// CÁLCULO DE FECHA
// ======================================================================

// Si hay rango y no hay fecha, calcular fecha exacta (en timezone Argentina)
if (!fecha && rango && rango !== 'exacto') {
  let daysToAdd = 0;
  if (rango === 'inmediato') daysToAdd = 1;
  else if (rango === '2semanas') daysToAdd = 14;
  else if (rango === '1mes') daysToAdd = 28;
  if (daysToAdd > 0) {
    fecha = addDays(hoyArgentina(), daysToAdd);
  }
}

// Si hay fechaRaw (input DD/MM/AAAA), validar y convertir
if (!fecha && fechaRaw) {
  const match = /^(\d{2})\/(\d{2})\/(\d{4})$/.exec(fechaRaw);
  if (match) {
    const day = parseInt(match[1], 10);
    const month = parseInt(match[2], 10) - 1;
    const year = parseInt(match[3], 10);
    const parsed = new Date(year, month, day);
    if (parsed.getDate() === day && parsed.getMonth() === month && parsed.getFullYear() === year) {
      const todayStr = hoyArgentina();
      const maxStr = addDays(todayStr, 90);  // ~3 meses
      const iso = String(year) + '-' + String(month + 1).padStart(2, '0') + '-' + String(day).padStart(2, '0');
      if (iso < todayStr) {
        accion = 'fecha_invalida';
        mensajeError = 'La fecha está en el pasado.';
      } else if (iso > maxStr) {
        accion = 'fecha_invalida';
        mensajeError = 'Solo podés reservar hasta 3 meses adelante.';
      } else {
        fecha = `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
      }
    } else {
      accion = 'fecha_invalida';
      mensajeError = 'La fecha no es válida (día o mes incorrecto).';
    }
  } else {
    accion = 'fecha_invalida';
    mensajeError = 'Formato incorrecto. Usá DD/MM/AAAA (ej: 15/07/2026).';
  }
}

// ======================================================================
// GUARDAR EN STATIC DATA
// ======================================================================
if (ctxKey && fecha) {
  staticData[ctxKey] = {
    fecha: fecha,
    rango: rango,
    slots: ctx.slots || []
  };
}

// ======================================================================
// DECIDIR ACCIÓN FINAL
// ======================================================================
if (!accion) {
  if (rango === 'exacto' && !fecha) {
    accion = 'pedir_fecha';
  } else if (fecha && slot) {
    accion = 'crear_turno';
  } else if (fecha) {
    accion = 'pedir_slot';
  } else {
    accion = 'pedir_rango';
  }
}

return [{
  json: {
    chat_id: chatId,
    comando: comando,
    accion: accion,
    fecha: fecha,
    slot: slot,
    rango: rango,
    fecha_inicio: fecha || '',
    mensaje_error: mensajeError
  }
}];

// ======================================================================
// HELPERS
// ======================================================================
function addDays(yyyy_mm_dd, n) {
  const [y, m, d] = yyyy_mm_dd.split('-').map(Number);
  const date = new Date(Date.UTC(y, m - 1, d));
  date.setUTCDate(date.getUTCDate() + n);
  const yy = date.getUTCFullYear();
  const mm = String(date.getUTCMonth() + 1).padStart(2, '0');
  const dd = String(date.getUTCDate()).padStart(2, '0');
  return `${yy}-${mm}-${dd}`;
}

// ======================================================================
// LEER SLOTS DEL HTTP RESPONSE
// ======================================================================
const items = $input.all();
let slots = [];

if (items.length > 0) {
  if (Array.isArray(items[0].json)) {
    slots = items[0].json;
  } else {
    slots = items.map(item => item.json);
  }
}
slots = slots.filter(function (s) { return s && typeof s.hora_inicio === "string" && s.disponible !== false; });

// chatId y fecha_inicio los leemos del Code - Decidir Paso (sobrevive al loop)
let chatId = '';
let fechaInicial = '';
let fechaInicio = '';
try {
  const codeData = $('Code - Decidir Paso').first().json;
  if (codeData) {
    chatId = codeData.chat_id || '';
    fechaInicial = codeData.fecha || '';
    fechaInicio = codeData.fecha_inicio || fechaInicial;
  }
} catch (e) {
  // fallback silencioso
}

// ======================================================================
// STATIC DATA: fecha REAL consultada (avanza con cada retry) + contador
// ======================================================================
const staticData = $getWorkflowStaticData('global');
const contadorKey = 'contador_' + chatId;
const fechaKey = 'fecha_' + chatId;
const ctxKey = chatId ? 'ctx_' + chatId : null;
let contador = staticData[contadorKey] || 0;
const fechaActual = staticData[fechaKey] || fechaInicial;

if (slots.length > 0) {
  // Guardar slots en staticData para resolver slot_numero después
  if (ctxKey) {
    const existing = staticData[ctxKey] || {};
    existing.slots = slots;
    staticData[ctxKey] = existing;
  }
  delete staticData[contadorKey];
  delete staticData[fechaKey];
  return [{
    json: {
      chat_id: chatId,
      fecha: fechaActual,
      fecha_inicio: fechaInicio,
      slots: slots,
      decision: 'found'
    }
  }];
}

// No hay slots. ¿Ya intentamos los 7 días?
const MAX_DIAS = 7;
if (contador >= MAX_DIAS - 1 || !fechaActual) {
  delete staticData[contadorKey];
  delete staticData[fechaKey];
  return [{
    json: {
      chat_id: chatId,
      fecha: fechaActual,
      fecha_inicio: fechaInicio,
      slots: [],
      decision: 'exhausted'
    }
  }];
}

// Retry: +1 día desde la fecha realmente consultada
staticData[contadorKey] = contador + 1;
const nextFecha = addDays(fechaActual, 1);
staticData[fechaKey] = nextFecha;
return [{
  json: {
    chat_id: chatId,
    fecha: nextFecha,
    fecha_inicio: fechaInicio,
    slots: [],
    decision: 'retry'
  }
}];

const input = ($input.all()[0] && $input.all()[0].json) || {};
const chatId = input.chat_id;
const fecha = input.fecha || '';
let slots = input.slots || [];
if (!Array.isArray(slots)) slots = [];
const disponibles = slots.filter(function (s) { return s.disponible !== false; });

// Un boton por slot (una fila cada uno). La FECHA viaja en el callback_data
// para que la seleccion sea STATELESS: no depende de $getWorkflowStaticData.
// Formato: cmd:crear:slot:HH:MM:f:YYYY-MM-DD  (<64 bytes, limite de Telegram)
const inlineKeyboard = disponibles.map(function (s) {
  return [{
    text: s.hora_inicio + (s.hora_fin ? ' - ' + s.hora_fin : ''),
    callback_data: 'cmd:crear:slot:' + s.hora_inicio + ':f:' + fecha
  }];
});

const texto = '\uD83D\uDD50 Horarios disponibles para el ' + fecha + ':\n\nElegi un horario \uD83D\uDC47';

// tg_body = payload listo para POST /sendMessage (lo envia el nodo HTTP siguiente)
return [{
  json: {
    chat_id: chatId,
    fecha: fecha,
    slots: disponibles,
    cantidad: disponibles.length,
    tg_body: {
      chat_id: chatId,
      text: texto,
      reply_markup: { inline_keyboard: inlineKeyboard }
    }
  }
}];

// Leer chat_id del Code - Decidir Paso (sobrevive al flow)
let chatId = '';
try {
  const codeData = $('Code - Decidir Paso').first().json;
  if (codeData) {
    chatId = codeData.chat_id || '';
  }
} catch (e) {
  // fallback silencioso
}

// fullResponse: true (c-27, design § D4 nota de implementacion) -- sin
// esto un 4xx tira excepcion antes de llegar aca y el chequeo de
// statusCode de abajo era codigo muerto (era el caso ANTES de c-27).
const input = ($input.all()[0] && $input.all()[0].json) || {};
const statusCode = input.statusCode;
const body = input.body || {};
const fecha = body.fecha;
const slot = body.hora_inicio;
const turnoId = body.id;
const errorStatus = typeof statusCode === 'number' && statusCode >= 400;
const errorDetail = body.detail || (errorStatus ? 'Error HTTP ' + statusCode : null);
const exito = !!turnoId && !errorStatus;

// Si la reserva se creo, arrancamos la captura de identidad (design § D3):
// captura_<chatId> es el UNICO lugar donde vive la conversacion (turno_id,
// paso, datos). expira_en preferiria la expiracion real del backend, pero
// POST /turnos no la expone (OQ-4) -- fallback a RESERVA_TEMPORAL_MINUTOS
// (default 10) + 1 minuto de gracia. Es una comodidad de UX, no el
// mecanismo de correctitud real: ese es el 409 de PUT /confirmar (D6).
if (exito && chatId) {
  const staticData = $getWorkflowStaticData('global');
  const minutos = Number($env.RESERVA_TEMPORAL_MINUTOS) || 10;
  const expiraEn = Date.now() + (minutos + 1) * 60000;
  staticData['captura_' + chatId] = {
    turno_id: turnoId,
    paso: 'dni',
    datos: {},
    expira_en: expiraEn
  };
}

return [{
  json: {
    chat_id: chatId,
    fecha: fecha,
    slot: slot,
    turno_id: turnoId,
    exito: exito,
    error: errorDetail
  }
}];

// Procesa la respuesta del usuario segun el paso pendiente en
// captura_<chatId> (design § D3/D4, D5, c-27). Este nodo es DUEÑO del
// estado de la conversacion -- lee y escribe su propio staticData; el
// gate del orquestador es solo un bit de ruteo, nunca una copia de estos
// datos.
let chatId = null;
try {
  chatId = $('Code - Decidir Paso').first().json.chat_id;
} catch (e) {}

const input = ($input.all()[0] && $input.all()[0].json) || {};
const respuesta = String(input.respuesta_captura || '').trim();

const staticData = $getWorkflowStaticData('global');
const capturaKey = chatId ? 'captura_' + chatId : null;
const captura = capturaKey ? staticData[capturaKey] : null;
const vigente = !!(captura && (!captura.expira_en || Date.now() <= captura.expira_en));

if (!vigente) {
  // Auto-sanacion (design § D4): el gate del orquestador decia
  // "pendiente" pero esta captura ya no existe o vencio en el store del
  // sub-flujo (TTL skew, escritura perdida, reinicio de n8n). No se envia
  // ningun mensaje desde aca -- el orquestador muestra el menu de ayuda al
  // recibir captura_pendiente: false, mostrar_ayuda: true desde
  // Code - Retorno Estado.
  return [{ json: { chat_id: chatId, decision: 'sin_match' } }];
}

const datos = captura.datos || {};
let decision;

if (captura.paso === 'dni') {
  // DNI argentino: 7 u 8 digitos, sin puntos ni guiones (spec: "A
  // malformed DNI is rejected without losing the reservation").
  if (!/^\d{7,8}$/.test(respuesta)) {
    decision = 'dni_invalido';
  } else {
    datos.dni = respuesta;
    decision = 'dni_valido';
  }
} else if (captura.paso === 'nombre') {
  // D5: nombre y apellido en un solo mensaje.
  const partes = respuesta.split(/\s+/).filter(Boolean);
  datos.nombre = partes[0] || respuesta;
  datos.apellido = partes.slice(1).join(' ') || datos.nombre;
  captura.paso = 'telefono';
  decision = 'nombre_ok';
} else if (captura.paso === 'telefono') {
  // D5: telefono y email (opcional) en un solo mensaje.
  const partes = respuesta.split(/[\s,]+/).filter(Boolean);
  datos.telefono = (partes[0] || '').replace(/\D/g, '');
  const posibleEmail = partes.slice(1).join(' ');
  if (/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(posibleEmail)) {
    datos.email = posibleEmail;
  }
  captura.paso = 'confirmar';
  decision = 'telefono_ok';
} else {
  decision = 'sin_match';
}

captura.datos = datos;
if (capturaKey) staticData[capturaKey] = captura;

return [{
  json: {
    chat_id: chatId,
    turno_id: captura.turno_id,
    decision: decision,
    dni: datos.dni || '',
    nombre: datos.nombre || '',
    apellido: datos.apellido || '',
    telefono: datos.telefono || '',
    email: datos.email || ''
  }
}];

// Branch de la busqueda de paciente (design § D1/D4, task 7.3): 200 =
// paciente existente, 404 = paciente nuevo. neverError + fullResponse en
// HTTP - GET Buscar Paciente son obligatorios -- sin ellos el 404 tira
// excepcion y este nodo nunca corre.
let chatId = null;
try {
  chatId = $('Code - Decidir Paso').first().json.chat_id;
} catch (e) {}

const input = ($input.all()[0] && $input.all()[0].json) || {};
const statusCode = input.statusCode;
const body = input.body || {};

const staticData = $getWorkflowStaticData('global');
const capturaKey = chatId ? 'captura_' + chatId : null;
const captura = capturaKey ? (staticData[capturaKey] || {}) : {};
const datos = captura.datos || {};

let decision;
if (statusCode === 200) {
  // Paciente existente (spec "Returning patient"): se completan los datos
  // guardados SIN volver a pedirselos al usuario.
  datos.nombre = body.nombre;
  datos.apellido = body.apellido;
  datos.telefono = body.telefono;
  captura.paso = 'confirmar';
  decision = 'encontrado';
} else {
  captura.paso = 'nombre';
  decision = 'no_encontrado';
}

captura.datos = datos;
if (capturaKey) staticData[capturaKey] = captura;

return [{
  json: {
    chat_id: chatId,
    turno_id: captura.turno_id,
    decision: decision,
    dni: datos.dni || '',
    nombre: datos.nombre || '',
    apellido: datos.apellido || '',
    telefono: datos.telefono || '',
    email: datos.email || ''
  }
}];

// Lee el resultado de HTTP - PUT Confirmar Turno. neverError + fullResponse
// (design § D4 nota de implementacion, D6): sin esas opciones un 409 tira
// excepcion y las ramas de abajo (7.9, 7.10) son inalcanzables.
let chatId = null;
try {
  chatId = $('Code - Decidir Paso').first().json.chat_id;
} catch (e) {}

const input = ($input.all()[0] && $input.all()[0].json) || {};
const statusCode = input.statusCode;
const body = input.body || {};
const detail = String(body.detail || '').toLowerCase();

const staticData = $getWorkflowStaticData('global');
const capturaKey = chatId ? 'captura_' + chatId : null;
const captura = capturaKey ? (staticData[capturaKey] || {}) : {};
const datos = captura.datos || {};

let decision = 'error';
if (typeof statusCode === 'number' && statusCode >= 200 && statusCode < 300) {
  decision = 'confirmado';
} else if (statusCode === 409 && detail.includes('expir')) {
  decision = 'expirado';
} else if (statusCode === 409 && detail.includes('turno activo')) {
  decision = 'paciente_turno_activo';
}

// Limpieza (design § D3, task 7.7): en los 3 desenlaces terminales se
// borran las 4 claves JUNTAS -- incluye el leak preexistente de ctx_ (y
// contador_/fecha_ del retry diario) que nunca se limpiaba tras una
// creacion exitosa. captura_pendiente saldra en false desde Code -
// Retorno Estado en el mismo round trip, asi que el gate del orquestador
// se limpia sin un mecanismo aparte.
if (decision === 'confirmado' || decision === 'expirado' || decision === 'paciente_turno_activo') {
  if (chatId) {
    delete staticData['captura_' + chatId];
    delete staticData['ctx_' + chatId];
    delete staticData['contador_' + chatId];
    delete staticData['fecha_' + chatId];
  }
}

return [{
  json: {
    chat_id: chatId,
    decision: decision,
    nombre: datos.nombre || '',
    apellido: datos.apellido || '',
    fecha: body.fecha || '',
    hora: body.hora_inicio || ''
  }
}];

