// Fan-in de TODAS las ramas terminales del sub-flujo (design § D3, task
// 7.0). Lee su propio store (captura_<chatId>) y devuelve el estado a
// quien invoco este workflow -- el orquestador (Code - Sync Captura) usa
// esto para mantener su gate en sincronia con la conversacion real en
// CADA dispatch, sea o no de creacion de turno.
let chatId = null;
try {
  chatId = $('Code - Decidir Paso').first().json.chat_id;
} catch (e) {}

const staticData = $getWorkflowStaticData('global');
const capturaKey = chatId ? 'captura_' + chatId : null;
const captura = capturaKey ? staticData[capturaKey] : null;
const capturaPendiente = !!(captura && (!captura.expira_en || Date.now() <= captura.expira_en));

// mostrar_ayuda: true SOLO en la auto-sanacion (design § D4) -- Code -
// Procesar Captura decidio 'sin_match' porque el gate del orquestador
// estaba pendiente pero esta captura ya no existe o vencio.
let mostrarAyuda = false;
try {
  const decidido = $('Code - Decidir Paso').first().json;
  if (decidido && decidido.accion === 'captura') {
    let procesado = null;
    try { procesado = $('Code - Procesar Captura').first().json; } catch (e) {}
    if (procesado && procesado.decision === 'sin_match') mostrarAyuda = true;
  }
} catch (e) {}

return [{
  json: {
    chat_id: chatId,
    captura_pendiente: capturaPendiente,
    expira_en: captura ? captura.expira_en : null,
    mostrar_ayuda: mostrarAyuda
  }
}];
